'use client'
/** Audio: the MATRIX card `audio-levels`. Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { audioBoard } from '@/lib/matrix/widgets/boards/audio'

const preset = audioBoard.find(p => p.id === 'audio-levels')!

export type MatrixAudioLevelsProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixAudioLevels(props: MatrixAudioLevelsProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
